// Solder Enclosure for Sip Smart Plant Waterer
// Outer: 140 x 100 x 45 mm, Wall: 2 mm

$fn = 40;
wall = 2.0;
width = 140;
depth = 100;
height = 45;
lid_height = 8;
radius = 4;

module rounded_box(w, d, h, r) {
    hull() {
        translate([-w/2 + r, -d/2 + r, 0]) cylinder(r=r, h=h);
        translate([ w/2 - r, -d/2 + r, 0]) cylinder(r=r, h=h);
        translate([-w/2 + r,  d/2 - r, 0]) cylinder(r=r, h=h);
        translate([ w/2 - r,  d/2 - r, 0]) cylinder(r=r, h=h);
    }
}

// Main Enclosure Base
module enclosure_base() {
    difference() {
        rounded_box(width, depth, height - lid_height, radius);
        // Inner cavity
        translate([0, 0, wall])
            rounded_box(width - 2*wall, depth - 2*wall, height, radius - 1);

        // USB Type-B port cutout for Uno
        translate([-width/2 - 1, 15, 6])
            cube([wall + 2, 13, 12]);

        // DC Power Barrel cutout
        translate([-width/2 - 1, -5, 6])
            cube([wall + 2, 10, 11]);

        // Water tubing exit hole (diameter 8mm)
        translate([-32, -depth/2 - 1, 18])
            rotate([-90, 0, 0])
                cylinder(r=4.2, h=wall + 2);

        // Soil sensor cable grommet cutout
        translate([width/2 - 10, -depth/2 - 1, 10])
            cube([12, wall + 2, 8]);
    }

    // Internal Mounting standoffs for Arduino Uno
    translate([-28 - 25, 15 - 20, wall]) cylinder(r=3, h=4);
    translate([-28 + 25, 15 - 20, wall]) cylinder(r=3, h=4);
    translate([-28 - 25, 15 + 20, wall]) cylinder(r=3, h=4);
    translate([-28 + 25, 15 + 20, wall]) cylinder(r=3, h=4);
}

// Snap-Fit Lid with OLED Display Window
module enclosure_lid() {
    translate([0, 0, height + 10]) {
        difference() {
            union() {
                rounded_box(width, depth, lid_height, radius);
                // Snap-fit lip
                translate([0, 0, -3])
                    rounded_box(width - 2*wall - 0.4, depth - 2*wall - 0.4, 3, radius - 1);
            }
            // Bevel cut
            translate([0, 0, -4])
                rounded_box(width - 4*wall, depth - 4*wall, 10, radius - 2);

            // OLED Display window
            translate([40, -22, -1])
                cube([25, 15, lid_height + 4], center=true);
        }
    }
}

enclosure_base();
enclosure_lid();

