/*
 * Solder Showcase: Sip — Smart Plant Waterer
 * Target: Arduino Uno (ATmega328P)
 * Pins:
 *   A0: Capacitive Soil Moisture Sensor Analog In
 *   D7: 5V Relay Control (Active LOW)
 *   A4: SSD1306 OLED SDA
 *   A5: SSD1306 OLED SCL
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

const int PIN_SOIL = A0;
const int PIN_RELAY = 7;

// Calibrated thresholds for capacitive sensor
const int DRY_THRESHOLD = 650;  // Raw ADC above this means dry soil
const int WET_THRESHOLD = 350;  // Raw ADC below this means moist soil
const unsigned long PUMP_DURATION_MS = 2500; // 2.5s watering dose

void setup() {
  Serial.begin(9600);
  pinMode(PIN_RELAY, OUTPUT);
  digitalWrite(PIN_RELAY, HIGH); // Relay off on boot (active LOW)

  if (display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    display.clearDisplay();
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(20, 24);
    display.println(F("Solder :: Sip"));
    display.setCursor(20, 36);
    display.println(F("Plant Sentinel"));
    display.display();
  }
  Serial.println(F("SYSTEM_READY"));
}

void loop() {
  int rawValue = analogRead(PIN_SOIL);
  int moisturePct = map(constrain(rawValue, WET_THRESHOLD, DRY_THRESHOLD), DRY_THRESHOLD, WET_THRESHOLD, 0, 100);

  // OLED refresh
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("SIP PLANT WATERER"));
  display.drawLine(0, 10, 128, 10, SSD1306_WHITE);

  display.setCursor(0, 18);
  display.print(F("Moisture: "));
  display.print(moisturePct);
  display.println(F("%"));

  display.drawRect(0, 30, 128, 12, SSD1306_WHITE);
  display.fillRect(2, 32, (int)(moisturePct * 1.24), 8, SSD1306_WHITE);

  if (rawValue >= 1020) {
    // Sensor disconnected or pull-up floating
    display.setCursor(0, 48);
    display.println(F("ALERT: PROBE DISCON"));
    Serial.println(F("SENSOR_ALERT"));
  } else if (rawValue > DRY_THRESHOLD) {
    // Dry condition detected -> trigger pump
    display.setCursor(0, 48);
    display.println(F("STATUS: WATERING..."));
    display.display();

    Serial.print(F("MOISTURE_LOW:"));
    Serial.print(moisturePct);
    Serial.println(F("%"));
    Serial.println(F("PUMP_ON"));

    digitalWrite(PIN_RELAY, LOW); // Turn on pump
    delay(PUMP_DURATION_MS);
    digitalWrite(PIN_RELAY, HIGH); // Turn off pump

    Serial.println(F("PUMP_OFF"));
  } else {
    // Soil moisture optimal
    display.setCursor(0, 48);
    display.println(F("STATUS: MOISTURE OK"));
    Serial.print(F("MOISTURE_OK:"));
    Serial.print(moisturePct);
    Serial.println(F("%"));
    Serial.println(F("PUMP_STANDBY"));
  }

  display.display();
  delay(1000);
}
